import { useState } from "react";
import {
  type ReverbState,
  reverbDevice,
} from "@/components/audio-ui/devices/reverb/device";
import { createReverbEngine } from "@/components/audio-ui/devices/reverb/engine";
import { ReverbPanel } from "@/components/audio-ui/devices/reverb/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useDeviceSignal } from "@/hooks/use-device-signal";
import { useMasterBus } from "@/hooks/use-master-bus";
import { useDemoSound } from "@/hooks/use-demo-source";

const MASTER_VOLUME = 0.7;

/**
 * A reverb you can plug in: its state, a panel that draws the tail it makes
 * and an engine that plays it, each its own file and none knowing the others.
 * Play the loop and drag the handle along: the decay time.
 */
export function BlockReverb() {
  const [state, setState] = useState<ReverbState>(() =>
    reverbDevice.defaults()
  );
  const master = useMasterBus(MASTER_VOLUME);
  const sound = useDemoSound("groove");
  const { engine } = useDeviceLoop({
    create: createReverbEngine,
    destination: master,
    sound,
    state,
  });
  const signal = useDeviceSignal(engine, reverbDevice);
  return (
    <div className="rounded-xl h-full w-full min-w-0">
      <ReverbPanel onValueChange={setState} signal={signal} value={state} />
    </div>
  );
}
